function rotPt(x,y,deg){ const a=deg*Math.PI/180, c=Math.cos(a), s=Math.sin(a); return [Math.round((x*c - y*s)*100)/100, Math.round((x*s + y*c)*100)/100]; }

function fromAngle(a, exit){ // a vehicle arriving from an arm rotated `a` degrees from the south arm
  const s=rotPt(30,330,a), m=rotPt(30,72,a);
  const ends={N:'Q 24 24 30 -80 L 30 -330', E:'Q 30 30 80 30 L 330 30', W:'Q -24 -24 -80 -30 L -330 -30', S:'Q -24 24 -30 80 L -30 330'};
  return `M${s[0]} ${s[1]} L${m[0]} ${m[1]} ${ends[exit]}`;
}

