const okmark = (x,y)=> `<g transform="translate(${x} ${y})"><circle r="13" fill="#2A9D5C"/><path d="M-6 0 L-2 5 L7 -5" fill="none" stroke="#fff" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/></g>`;
